const e="वयस्क",t="आगमन",o="आने वाले",s="बुक हो गया",a="बच्चे",n="साफ़ किया गया",r="प्रस्थान",i="ईमेल",h="होटल",d="हाउसकीपिंग",l="जाँचा गया",p="जाने वाले",v="नाम",c="भरा हुआ",u="फ़ोन",y="प्रॉपर्टी",m="कमरे",g={"A cancellation gets its deposit back any time before arrival.":"आगमन से पहले कभी भी रद्द करने पर जमा राशि लौटा दी जाती है।","A cancellation up to {days} days before arrival gets its deposit back; later, or not arriving, the hotel keeps it.":"आगमन से {days} दिन पहले तक रद्द करने पर जमा राशि लौटा दी जाती है; उसके बाद, या न आने पर, होटल उसे रख लेता है।","A reservation's link stops working a month after the stay, and opens only the reservation it was made for.":"आरक्षण का लिंक ठहरने के एक महीने बाद काम करना बंद कर देता है, और केवल उसी आरक्षण को खोलता है जिसके लिए बना था।","Add your hotel":"अपना होटल जोड़ें",Adults:e,"Anything the hotel should know":"कुछ भी जो होटल को जानना चाहिए",Arrival:t,Arriving:o,"Book a room":"कमरा बुक करें","Book it":"बुक करें","Book this room":"यह कमरा बुक करें",Booked:s,"Booked: {number}":"बुक हो गया: {number}","Business date {bd}":"व्यावसायिक तिथि {bd}","Cancel it":"रद्द करें","Cancel the reservation":"आरक्षण रद्द करें","Cancel this reservation?":"यह आरक्षण रद्द करें?","Cancelled before arrival, its deposit is given back.":"आगमन से पहले रद्द होने पर इसकी जमा राशि लौटा दी जाती है।","Cancelled up to {days} days before arrival, its deposit is given back; later, the hotel keeps it.":"आगमन से {days} दिन पहले तक रद्द होने पर इसकी जमा राशि लौटा दी जाती है; उसके बाद होटल उसे रख लेता है।","Check in":"चेक इन करें","Check out":"चेक आउट करें","Check-in from {in}; check-out by {out}.":"चेक-इन {in} से; चेक-आउट {out} तक।","Check-outs and the night audit put rooms here to clean.":"चेक-आउट और रात्रि ऑडिट कमरों को सफ़ाई के लिए यहाँ रखते हैं।",Children:a,Cleaned:n,"Close the night of {bd}?":"{bd} की रात बंद करें?","Dates and guests":"तारीखें और मेहमान",Departure:r,Email:i,"Every room is done":"हर कमरा हो गया","Front desk":"फ्रंट डेस्क","Go to the front desk":"फ्रंट डेस्क पर जाएँ",Hotel:h,Housekeeping:d,"In the house":"होटल में",Inspected:l,"Its nights are given up.":"इसकी रातें छोड़ दी जाती हैं।","Keep your reservation's link: it is how you see or cancel it.":"अपने आरक्षण का लिंक रखें: इसी से आप उसे देख या रद्द कर सकते हैं।",Leaving:p,"Mark cleaned":"साफ़ चिह्नित करें","Mark inspected":"जाँची हुई चिह्नित करें",Name:"नाम","No property yet":"अभी कोई प्रॉपर्टी नहीं","No room is free for every night of these dates. Try other dates.":"इन तारीखों की हर रात के लिए कोई कमरा खाली नहीं है। अन्य तारीखें आज़माएँ।","Nobody.":"कोई नहीं।",Occupied:c,"Open {property_name}":"{property_name} खोलें","Page not found":"पेज नहीं मिला",Phone:u,Property:y,"Room charges are posted to every stay in the house, reservations that did not arrive become no-shows, and the next day opens.":"होटल में हर ठहराव पर कमरे का शुल्क पोस्ट होता है, जो आरक्षण नहीं आए वे न आने वाले बन जाते हैं, और अगला दिन खुलता है।","Room {room}":"कमरा {room}",Rooms:m,"Rooms are not booked online here":"यहाँ कमरे ऑनलाइन बुक नहीं होते","Rooms free":"खाली कमरे","Run the night audit":"नाइट ऑडिट चलाएँ","See the rooms free":"खाली कमरे देखें","Set the first one on the property, with Set the Business Date.":"पहली तिथि प्रॉपर्टी पर सेट करें, “Set the Business Date” से।","Skip to content":"सामग्री पर जाएँ","Sleeps {sleeps} · {nights} nights · deposit {deposit}":"{sleeps} लोग · {nights} रातें · जमा {deposit}","Thank you: your request is in.":"धन्यवाद: आपका अनुरोध मिल गया।","The address may not be quite right. Please get in touch with the hotel directly.":"हो सकता है पता बिल्कुल सही न हो। कृपया सीधे होटल से संपर्क करें।","The hotel has no business date yet":"होटल की अभी कोई व्यावसायिक तिथि नहीं है","The night of {value} is closed: {value2} rooms charged, {value3} no-shows":"{value} की रात बंद हुई: {value2} कमरों पर शुल्क, {value3} नहीं आए","This link does not work":"यह लिंक काम नहीं करता","To clean":"साफ़ करने को","Total {total}; deposit {deposit}, of which {paid} is paid.":"कुल {total}; जमा {deposit}, जिसमें से {paid} चुकाया गया।","Total {total}; deposit {deposit}, taken by the hotel.":"कुल {total}; जमा {deposit}, होटल द्वारा लिया जाएगा।","Where your reservation is sent":"जहाँ आपका आरक्षण भेजा जाता है","Why you are cancelling (optional)":"रद्द करने का कारण (वैकल्पिक)","Your deposit is being given back.":"आपकी जमा राशि लौटाई जा रही है।","Your deposit is kept, as the hotel's terms say.":"होटल की शर्तों के अनुसार आपकी जमा राशि रख ली गई है।","Your details":"आपका विवरण","Your reservation":"आपका आरक्षण","{arrival} to {departure}":"{arrival} से {departure}","{guest_name} has left":"{guest_name} चले गए","{guest_name} is in":"{guest_name} आ गए","{n} to do":"{n} करने को","{room_type} at {property}, {arrival} to {departure}.":"{property} में {room_type}, {arrival} से {departure} तक।"};export{e as Adults,t as Arrival,o as Arriving,s as Booked,a as Children,n as Cleaned,r as Departure,i as Email,h as Hotel,d as Housekeeping,l as Inspected,p as Leaving,v as Name,c as Occupied,u as Phone,y as Property,m as Rooms,g as default};
